SAFE_MODE = True

import os
from flask import Flask, render_template, abort

app = Flask(__name__)

# List of approved CSS classes
APPROVED_CSS_CLASSES = {'class1', 'class2', 'class3'}

def validate_css_classes(html_content):
    for class_name in APPROVED_CSS_CLASSES:
        if f'class="{class_name}"' in html_content:
            continue
    return False

@app.route('/dashboard')
def serve_dashboard():
    if SAFE_MODE:
        html_file_path = 'path/to/your/dashboard.html'
        if not os.path.exists(html_file_path):
            abort(404)
        with open(html_file_path, 'r') as file:
            content = file.read()
            if not validate_css_classes(content):
                abort(403)  # Forbidden if validation fails
        return render_template('dashboard.html')
    else:
        return "SAFE_MODE is off, serving dashboard without validation."

if __name__ == '__main__':
    app.run(debug=True)

